import{_ as a,o as e,c as i,a6 as t}from"./chunks/framework.BrkgobfX.js";const k=JSON.parse('{"title":"Commands","description":"Claude Code 中文手册 · 斜杠命令与 .claude/commands 自定义命令，及与 Skills 体系的迁移关系","frontmatter":{"title":"Commands","description":"Claude Code 中文手册 · 斜杠命令与 .claude/commands 自定义命令，及与 Skills 体系的迁移关系","source":"https://daiw.org/manual/claude-code/custom-commands"},"headers":[],"relativePath":"manual/agent/claude-code/custom-commands.md","filePath":"manual/agent/claude-code/custom-commands.md"}'),n={name:"manual/agent/claude-code/custom-commands.md"};function d(l,s,o,c,r,p){return e(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h1><blockquote><p>Claude Code 中文手册 · 斜杠命令与 .claude/commands 自定义命令，及与 Skills 体系的迁移关系</p></blockquote><p><strong>Commands（自定义命令）</strong> 是你用 Markdown 写的一段固定 prompt，在会话里以 <code>/命令名</code> 调用。v2.1 起，旧版 <code>.claude/commands/*.md</code> 已<strong>并入 Skills 体系</strong>——文件格式兼容、行为等价，新内容应写在 <code>.claude/skills/&lt;name&gt;/SKILL.md</code>。本篇说明两种写法的差异、存放位置与日常用法。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>技能（Skills）的完整机制见 <a href="/Front2Full/manual/agent/claude-code/skills">Skills</a>。本篇聚焦「命令」视角：如何命名、调用、传参，以及从旧目录迁移。</p></div><h2 id="两种形态-一套机制" tabindex="-1">两种形态，一套机制 <a class="header-anchor" href="#两种形态-一套机制" aria-label="Permalink to &quot;两种形态，一套机制&quot;">​</a></h2><table tabindex="0"><thead><tr><th>形态</th><th>路径</th><th>状态</th></tr></thead><tbody><tr><td>旧版自定义命令</td><td><code>.claude/commands/&lt;name&gt;.md</code> 或 <code>~/.claude/commands/&lt;name&gt;.md</code></td><td><strong>仍兼容</strong>，建议迁移到 skills</td></tr><tr><td>技能（推荐）</td><td><code>.claude/skills/&lt;name&gt;/SKILL.md</code> 或 <code>~/.claude/skills/&lt;name&gt;/SKILL.md</code></td><td>当前标准写法</td></tr></tbody></table><p>两者都会出现在 <code>/</code> 补全菜单里；Claude 也可根据 <code>description</code> 自动判断是否调用（除非设置了 <code>disable-model-invocation</code>）。</p><h2 id="最小自定义命令-旧版路径" tabindex="-1">最小自定义命令（旧版路径） <a class="header-anchor" href="#最小自定义命令-旧版路径" aria-label="Permalink to &quot;最小自定义命令（旧版路径）&quot;">​</a></h2><p>在项目根创建 <code>.claude/commands/commit.md</code>：</p><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">按 Conventional Commits 规范提交当前改动</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">1.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 运行 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`git status\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 与 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`git diff\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 查看变更</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">2.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 起草简洁的 commit message（英文，focus on why）</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">3.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 执行 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`git add\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 与 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`git commit\`</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">4.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 不要 push，除非用户明确要求</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>保存后执行 <code>/reload-skills</code>（或重启会话），即可在终端输入 <code>/commit</code> 调用。</p><h2 id="推荐-写成-skill-md" tabindex="-1">推荐：写成 SKILL.md <a class="header-anchor" href="#推荐-写成-skill-md" aria-label="Permalink to &quot;推荐：写成 SKILL.md&quot;">​</a></h2><p>同一逻辑迁移到 <code>.claude/skills/commit/SKILL.md</code>：</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">commit</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">按 Conventional Commits 规范提交当前改动</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">disable-model-invocation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">allowed-tools</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Bash(git status) Bash(git diff) Bash(git add *) Bash(git commit *)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1. 运行 \`git status\` 与 \`git diff\` 查看变更</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">2. 起草简洁的 commit message（英文，focus on why）</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">3. 执行 \`git add\` 与 \`git commit\`</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">4. 不要 push，除非用户明确要求</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>相比纯 <code>.md</code> 命令文件，SKILL 额外支持：</p><table tabindex="0"><thead><tr><th>能力</th><th>作用</th></tr></thead><tbody><tr><td><code>allowed-tools</code></td><td>声明工具白名单，减少反复点确认</td></tr><tr><td><code>disable-model-invocation</code></td><td>仅手动 <code>/commit</code> 触发，避免 Claude 误提交</td></tr><tr><td><code>arguments</code> / <code>$ARGUMENTS</code></td><td>支持 <code>/commit fix: login bug</code> 传参</td></tr><tr><td><code>context: fork</code> + <code>agent</code></td><td>在独立 <a href="/Front2Full/manual/agent/claude-code/agents">Agent</a> 里执行</td></tr></tbody></table><h2 id="存放位置与作用域" tabindex="-1">存放位置与作用域 <a class="header-anchor" href="#存放位置与作用域" aria-label="Permalink to &quot;存放位置与作用域&quot;">​</a></h2><table tabindex="0"><thead><tr><th>位置</th><th>影响范围</th><th>是否进 git</th></tr></thead><tbody><tr><td><code>~/.claude/commands/</code> 或 <code>~/.claude/skills/</code></td><td>你所有项目</td><td>否</td></tr><tr><td><code>.claude/commands/</code> 或 <code>.claude/skills/</code></td><td>当前仓库协作者</td><td>是（推荐团队共享）</td></tr><tr><td>插件内置</td><td>安装插件的用户</td><td>由插件分发</td></tr></tbody></table><p>项目级命令应提交进仓库，让团队共用同一套 <code>/review</code>、<code>/deploy</code> 等工作流。</p><h2 id="传参" tabindex="-1">传参 <a class="header-anchor" href="#传参" aria-label="Permalink to &quot;传参&quot;">​</a></h2><p>在 SKILL frontmatter 声明参数：</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">explain</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">用通俗语言解释指定文件或概念</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">argument-hint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">文件路径或概念名</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">请用中文向初级开发者解释：$ARGUMENTS</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>调用：<code>/explain src/auth/token.ts</code></p><p>旧版 <code>.claude/commands/*.md</code> 同样支持 <code>$ARGUMENTS</code> 与位置参数 <code>$0</code>、<code>$1</code>（⚠️ v2.1.301 起最多只填充前 64 个参数名，每个最长 64 个字符）。</p><h2 id="堆叠调用" tabindex="-1">堆叠调用 <a class="header-anchor" href="#堆叠调用" aria-label="Permalink to &quot;堆叠调用&quot;">​</a></h2><p>v2.1.199+ 支持在一次输入里串联多个技能，例如：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/deploy-staging /run-tests 确认通过后部署</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>最多可一次性加载 <strong>5</strong> 个前置技能的上下文（详见 <a href="/Front2Full/manual/agent/claude-code/skills">Skills · 堆叠调用</a>）。</p><h2 id="相关斜杠命令" tabindex="-1">相关斜杠命令 <a class="header-anchor" href="#相关斜杠命令" aria-label="Permalink to &quot;相关斜杠命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/skills</code></td><td>列出全部技能/命令，按名称过滤，按 <code>t</code> 按 token 排序，按 <code>Space</code> 切换可见性</td></tr><tr><td><code>/reload-skills</code></td><td>热重载磁盘上的技能与命令目录（v2.1.152+），无需重启会话</td></tr><tr><td><code>/disable-slash-commands</code></td><td>本次会话禁用全部 skills 与命令（排查问题时用）</td></tr></tbody></table><p>命令行等价：<code>claude --disable-slash-commands</code>。</p><h2 id="与内置命令的区别" tabindex="-1">与内置命令的区别 <a class="header-anchor" href="#与内置命令的区别" aria-label="Permalink to &quot;与内置命令的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>例子</th><th>谁维护</th></tr></thead><tbody><tr><td>内置斜杠命令</td><td><code>/clear</code>、<code>/model</code>、<code>/memory</code></td><td>Anthropic 随 Claude Code 发布</td></tr><tr><td>随附技能（bundled skills）</td><td><code>/batch</code>、<code>/code-review</code></td><td>内置，可用 <code>disableBundledSkills</code> 关闭</td></tr><tr><td>自定义命令 / 项目技能</td><td><code>/commit</code>、<code>/deploy</code></td><td>你或团队写在 <code>.claude/</code></td></tr><tr><td>插件技能</td><td><code>skill-creator:...</code></td><td>第三方插件</td></tr></tbody></table><p>自定义命令<strong>不会</strong>覆盖内置命令名；重名时以命名空间或加载顺序为准，建议避免与内置 <code>/init</code>、<code>/help</code> 等冲突。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ol><li><strong>「改了文件却没出现在菜单里」</strong>——执行 <code>/reload-skills</code>，或检查 frontmatter 是否缺少 <code>description</code>（影响自动调用，不影响手动 <code>/name</code>）。</li><li><strong>「命令能执行危险操作」</strong>——对 <code>/deploy</code>、<code>/rm</code> 类命令务必加 <code>disable-model-invocation: true</code>，并用 <code>permissions.deny</code> 限制 Bash。</li><li><strong>「<code>.claude/commands</code> 和 <code>skills</code> 二选一」</strong>——可共存，但同一逻辑只维护一份，优先 skills。</li><li><strong>「<code>--add-dir</code> 会自动加载额外目录的命令」</strong>——只额外发现 <code>.claude/skills/</code>，不会加载其它目录下的完整 <code>.claude/</code> 配置（见 <a href="/Front2Full/manual/agent/claude-code/commands-session">会话管理命令</a>；v2.1.309 起 <code>--add-dir</code> 目录里的技能若与已有技能重名，会以 <code>&lt;folder&gt;:&lt;name&gt;</code> 的形式提供）。</li><li><strong>「名字以 <code>anthropic-skills:</code> 开头的命令不见了」</strong>——⚠️ v2.1.282 起这个命名空间保留给从 claude.ai 同步的技能，落在其中的命令文件、技能文件夹与工作流命令不再加载，换个名字即可（同版本对 <code>claude-ai</code> 的保留已在 v2.1.283 撤回）。另外 v2.1.292 起超过 256 个字符的 <code>name</code> 会被忽略，v2.1.299 起文件或文件夹名含隐藏/双向控制字符、空白类字符或 <code>&lt;&gt;</code> 的技能与命令不再提供，重命名后才会加载。</li></ol><h2 id="建议沉淀顺序" tabindex="-1">建议沉淀顺序 <a class="header-anchor" href="#建议沉淀顺序" aria-label="Permalink to &quot;建议沉淀顺序&quot;">​</a></h2><ol><li>把<strong>每周重复口述</strong>的多步骤流程写成项目技能（如 <code>/pr-checklist</code>）。</li><li>有副作用的操作加 <code>disable-model-invocation</code> + <code>allowed-tools</code>。</li><li>需要跨项目复用时，放到 <code>~/.claude/skills/</code>。</li><li>需要团队统一分发时，打包成<a href="/Front2Full/manual/agent/claude-code/plugins">插件</a>。</li></ol><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="/Front2Full/manual/agent/claude-code/skills">Skills</a>——frontmatter 全表、<code>context: fork</code>、插件技能命名空间</li><li><a href="/Front2Full/manual/agent/claude-code/agents">Agents</a>——让技能在独立 subagent 中执行</li><li><a href="/Front2Full/manual/agent/claude-code/plugins">Plugins</a>——把命令/技能打包成可分发插件</li><li><a href="/Front2Full/manual/agent/claude-code/commands-customization">自定义与扩展</a>——MCP、Hooks、插件一览</li></ul>`,40)])])}const m=a(n,[["render",d]]);export{k as __pageData,m as default};
